import React from 'react'
import { BodyContainer, DataContainer, IconButton } from '../../styles/global'
import { IoMdAddCircleOutline } from 'react-icons/io'
import { MdOutlineClear } from 'react-icons/md'
import { FiStar, FiArchive, FiTrash2 } from 'react-icons/fi'
import { IoMdSearch } from 'react-icons/io'
import { getTags } from '../../utils'
import { Card, defaultContent } from '../../components/Card'
import uuid from 'react-uuid'
import {
  EntryList,
  MenuContainer,
  MenuBarContainer,
  DateContainer,
  ActionsContainer,
  SearchContainer,
  SelectedPage,
} from './styles'
import { database } from '../../services/firebase'
import { collection, query, where, getDocs, doc, addDoc, setDoc } from 'firebase/firestore'

import { FiLock } from 'react-icons/fi'
import { UserAuth } from '../../contexts/AuthContext'
import { useDashboard } from '../../contexts/DashboardContext'
import { HeaderPortal } from '../../components/HeaderPortal'
import userImg from '../../assets/user.png'
import { FiEye } from 'react-icons/fi'
import { IoMdArrowDropdown, IoMdArrowDropleft } from 'react-icons/io'
import { VerticalBar, Page } from '../../components/VerticalBar'
import { BsJournalBookmark } from 'react-icons/bs'
import { GoTag } from 'react-icons/go'
import { CgTemplate } from 'react-icons/cg'

interface IEntry {
  uid: string
  id: string
  content: string
  date: string
  createdAt: string
}

const Dashboard: React.FC = () => {
  const { selectedDate, setSelectedDate } = useDashboard()
  const [collapsed, setCollapsed] = React.useState(false)
  const [searchContent, setSearchContent] = React.useState('')
  const [entries, setEntries] = React.useState<IEntry[]>([])
  const { user, logOut } = UserAuth()
  const startDate = new Date().toISOString().split('T')[0]
  const dateRef = React.useRef<HTMLInputElement>(null)

  const [selectedTag, setSelectedTag] = React.useState('')

  const handleCollapseExpand = async (state: boolean) => {
    setCollapsed(state)
    entries.map((entry) => {
      const objContent = JSON.parse(entry.content)
      handleChangeEntry(entry.id, JSON.stringify({ ...objContent, collapsed: state }))
    })
  }

  const availableTags = [
    'favorite',
    'journal',
    'archive',
    'trash',
    ...Array.from(new Set(entries.flatMap((entry) => getTags(entry.content))))
      .filter((tag) => !['favorite', 'journal', 'archive', 'trash', 'template'].includes(tag))
      .sort(),
  ]

  const pages = [
    { name: 'All', icon: FiEye, items: undefined },
    { name: 'Favorites', icon: FiStar, items: undefined },
    { name: 'Journal', icon: BsJournalBookmark, items: undefined },
    {
      name: 'Tags',
      icon: GoTag,
      items: availableTags.filter(
        (tag) => !['favorite', 'journal', 'archive', 'trash', 'template'].includes(tag)
      ),
    },
    { name: 'Archive', icon: FiArchive, items: undefined },
    { name: 'Trash', icon: FiTrash2, items: undefined },
  ]

  const [selectedPage, setSelectedPage] = React.useState<Page>({
    name: 'All',
    icon: FiEye,
    items: undefined,
  })

  const handleLockAll = async () => {
    entries.map((entry) => {
      const objContent = JSON.parse(entry.content)
      handleChangeEntry(entry.id, JSON.stringify({ ...objContent, locked: true }))
    })
  }

  const handleLogout = async () => {
    try {
      await logOut()
    } catch (error) {
      console.log(error)
    }
  }

  const handleDateChanged = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedDate(event.target.value)
  }

  const search = async (value: string) => {
    setSearchContent(value)
  }

  const isArchived = (entry: IEntry) => getTags(entry.content).includes('archive')

  const isTrash = (entry: IEntry) => getTags(entry.content).includes('trash')

  const isHidden = (entry: IEntry) => isArchived(entry) || isTrash(entry)

  async function handleAddNewEntry(event: any) {
    const tags: string[] = []

    if (selectedPage.name === 'Favorites') {
      tags.push('favorite')
    }

    if (selectedPage.name === 'Journal') {
      tags.push('journal')
    }

    if (selectedPage.name === 'Archive') {
      tags.push('archive')
    }

    if (selectedPage.name === 'Trash') {
      tags.push('trash')
    }

    if (selectedPage.name === 'Templates') {
      tags.push('template')
    }

    if (selectedPage.name === 'Tags' && selectedTag) {
      tags.push(selectedTag)
    }

    const newEntry: IEntry = {
      uid: user.uid,
      id: uuid(),
      content: JSON.stringify({
        ...defaultContent,
        tags,
      }),
      date: selectedDate,
      createdAt: new Date().toISOString(),
    }
    scrollToTop()
    const newEntries = [...entries, newEntry]
    newEntries.sort((a, b) => {
      if (a.date > b.date) return -1
      if (a.date < b.date) return 1
      if (a.createdAt > b.createdAt) return -1
      if (a.createdAt < b.createdAt) return 1
      return 0
    })
    setEntries(newEntries)
    const userDocRef = doc(database, 'users', user.uid)
    const entriesRef = collection(userDocRef, 'entries')
    await addDoc(entriesRef, newEntry)
  }

  async function fetchEntries() {
    const userDocRef = doc(database, 'users', user.uid)
    const entriesRef = collection(userDocRef, 'entries')
    const querySnapshot = await getDocs(entriesRef)
    const entries: IEntry[] = []
    querySnapshot.forEach((doc) => {
      let newEntry = doc.data() as IEntry
      if (!newEntry.createdAt) {
        newEntry.createdAt = newEntry.date
      }
      entries.push(newEntry)
    })
    entries.sort((a, b) => {
      if (a.date > b.date) return -1
      if (a.date < b.date) return 1
      if (a.createdAt > b.createdAt) return -1
      if (a.createdAt < b.createdAt) return 1
      return 0
    })
    setEntries(entries)
  }

  React.useEffect(() => {
    fetchEntries()
  }, [])

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    })
  }

  const handleDeleteEntry = async (id: string) => {
    const entry = entries.find((e) => e.id === id)

    if (!entry) {
      return
    }

    const content = JSON.parse(entry.content)

    const tags = Array.from(new Set([...(content.tags || []), 'trash'])).filter(
      (tag) => tag !== 'archive'
    )

    await handleChangeEntry(
      id,
      JSON.stringify({
        ...content,
        tags,
      })
    )
  }

  const handleChangeEntry = async (id: string, content: string) => {
    const newEntries = entries.map((entry) => {
      if (entry.id === id) {
        entry.content = content
      }
      return entry
    })
    setEntries(newEntries)

    const changedEntry = entries.find((entry) => entry.id === id)
    if (changedEntry) {
      changedEntry.content = content
      const userDocRef = doc(database, 'users', user.uid)
      const entriesRef = collection(userDocRef, 'entries')
      const userQuery = query(entriesRef, where('id', '==', id))
      const querySnapshot = await getDocs(userQuery)
      querySnapshot.forEach((document) => {
        setDoc(doc(database, `users/${user.uid}/entries`, document.id), changedEntry)
      })
    }
  }

  let count = 0
  const isLoggedIn =
    user !== null &&
    user.displayName !== undefined &&
    user.photoURL !== null &&
    user.photoURL !== undefined

  const SelectedPageIcon = searchContent.trim() === '' ? selectedPage.icon : IoMdSearch
  return (
    <BodyContainer>
      <HeaderPortal>
        {isLoggedIn && (
          <MenuContainer>
            <SelectedPage>
              <SelectedPageIcon />
              {searchContent.trim() === '' ? selectedPage.name : 'Search'}
            </SelectedPage>
            {selectedPage.name == 'Journal' ? (
              <DateContainer>
                <input
                  title="Select date"
                  ref={dateRef}
                  type="date"
                  defaultValue={startDate}
                  onChange={handleDateChanged}
                />
              </DateContainer>
            ) : (
              <></>
            )}

            <SearchContainer>
              <input
                placeholder="Search"
                value={searchContent}
                onChange={(e) => search(e.target.value)}
              />

              <IconButton title="Clear search" onClick={() => setSearchContent('')}>
                <MdOutlineClear />
              </IconButton>
            </SearchContainer>

            <ActionsContainer>
              <IconButton title="Lock all notes" onClick={handleLockAll}>
                <FiLock />
              </IconButton>

              {collapsed ? (
                <IconButton title="Expand all notes" onClick={() => handleCollapseExpand(false)}>
                  <IoMdArrowDropleft />
                </IconButton>
              ) : (
                <IconButton title="Collapse all notes" onClick={() => handleCollapseExpand(true)}>
                  <IoMdArrowDropdown />
                </IconButton>
              )}

              <IconButton title="Add note" onClick={handleAddNewEntry}>
                <IoMdAddCircleOutline />
              </IconButton>
            </ActionsContainer>
          </MenuContainer>
        )}

        {isLoggedIn && (
          <MenuBarContainer>
            <img
              title="Logout"
              src={user.photoURL ? user.photoURL : userImg}
              onError={({ currentTarget }) => {
                currentTarget.onerror = null
                currentTarget.src = userImg
              }}
              alt="User photograph"
              onClick={() => handleLogout()}
            />
          </MenuBarContainer>
        )}
      </HeaderPortal>
      <DataContainer>
        <EntryList>
          {entries.map((entry) => {
            const tags = getTags(entry.content)

            const visible =
              searchContent.trim() === ''
                ? (selectedPage.name === 'All' &&
                    !tags.includes('archive') &&
                    !tags.includes('trash')) ||
                  (selectedPage.name === 'Favorites' &&
                    tags.includes('favorite') &&
                    !tags.includes('archive') &&
                    !tags.includes('trash')) ||
                  (selectedPage.name === 'Journal' &&
                    tags.includes('journal') &&
                    !tags.includes('archive') &&
                    !tags.includes('trash')) ||
                  (selectedPage.name === 'Templates' &&
                    tags.includes('template') &&
                    !tags.includes('archive') &&
                    !tags.includes('trash')) ||
                  (selectedPage.name === 'Archive' && tags.includes('archive')) ||
                  (selectedPage.name === 'Trash' && tags.includes('trash')) ||
                  (selectedPage.name === 'Tags' &&
                    selectedTag !== '' &&
                    tags.includes(selectedTag) &&
                    !tags.includes('archive') &&
                    !tags.includes('trash'))
                : entry.content.toLowerCase().includes(searchContent.toLowerCase())

            return visible ? (
              <Card
                key={entry.id}
                id={entry.id}
                date={entry.date}
                number={(count = count + 1)}
                content={entry.content}
                onDeleteCard={handleDeleteEntry}
                onChangeContent={handleChangeEntry}
                tags={availableTags.filter(
                  (tag) => !['favorite', 'archive', 'trash'].includes(tag)
                )}
              />
            ) : (
              <div key={entry.id} />
            )
          })}
        </EntryList>
      </DataContainer>
      <VerticalBar
        pages={pages}
        selectedPage={selectedPage}
        setSelectedPage={setSelectedPage}
        setSelectedTag={setSelectedTag}
      />{' '}
    </BodyContainer>
  )
}

export default Dashboard
